<?php
require 'common.php';require_admin();$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=(string)($_POST['type']??'');$name=trim((string)($_POST['name']??''));if($name!==''){if($type==='brand'){$rows=brands();if(!in_array($name,array_column($rows,'name'),true)){$rows[]=['name'=>$name,'slug'=>normalize($name)];save_json('brands',$rows);audit('brand_add',$name);$notice='تمت إضافة العلامة.';}}elseif($type==='category'){$rows=categories();if(!in_array($name,array_column($rows,'name'),true)){$rows[]=['name'=>$name,'icon'=>'⚙','children'=>[]];save_json('categories',$rows);audit('category_add',$name);$notice='تمت إضافة القسم.';}}}}
admin_head('الأقسام والعلامات');?><?php if($notice):?><div class="ok-box"><?=e($notice)?></div><?php endif;?>
<section class="admin-grid two"><article class="panel"><div class="panel-head"><div><span>BRANDS</span><h2>العلامات التجارية</h2></div><b><?=count(brands())?></b></div><form method="post" class="admin-search"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="type" value="brand"><input name="name" placeholder="اسم العلامة التجارية" required><button>إضافة</button></form><div class="tag-cloud"><?php foreach(brands() as$b):?><span><?=e((string)($b['name']??''))?></span><?php endforeach;?></div></article><article class="panel"><div class="panel-head"><div><span>CATEGORIES</span><h2>الأقسام الرئيسية</h2></div><b><?=count(categories())?></b></div><form method="post" class="admin-search"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="type" value="category"><input name="name" placeholder="اسم القسم" required><button>إضافة</button></form><div class="taxonomy-list"><?php foreach(categories() as$c):?><div><b><?=e((string)($c['name']??''))?></b><small><?=e(implode(' • ',array_slice($c['children']??[],0,4)))?></small></div><?php endforeach;?></div></article></section><?php admin_foot();?>